
import React, { useState, useEffect } from 'react';
import { AdminVerificationRequest } from '../../types';
import { verificationApi } from '../../api/verification';
import { Loader2, Eye, User as UserIcon, X, AlertTriangle } from 'lucide-react';
import RejectModal from '../RejectModal';

interface AdminVerificationsSectionProps {
  onNotify: (type: 'success' | 'error', message: string) => void;
}

const AdminVerificationsSection: React.FC<AdminVerificationsSectionProps> = ({ onNotify }) => {
  const [requests, setRequests] = useState<AdminVerificationRequest[]>([]);
  const [loading, setLoading] = useState(false);
  const [reviewing, setReviewing] = useState<{ req: AdminVerificationRequest, url: string, userId: string } | null>(null);
  const [imageLoading, setImageLoading] = useState(false);
  const [imageError, setImageError] = useState(false);
  const [actionLoading, setActionLoading] = useState<Record<string, boolean>>({});
  const [rejectModal, setRejectModal] = useState<{ isOpen: boolean; userId: string | null }>({ isOpen: false, userId: null });

  useEffect(() => {
      fetchRequests();
  }, []);

  const fetchRequests = async () => {
      setLoading(true);
      try {
          const list = await verificationApi.getPendingRequests();
          setRequests(list);
      } catch (e) {
          console.error(e);
          onNotify('error', 'Failed to fetch verifications');
      } finally {
          setLoading(false);
      }
  };

  const openReviewModal = async (req: AdminVerificationRequest) => {
      const targetUserId = req.userId || (req as any)._id;
      if (!targetUserId) {
          onNotify('error', "Invalid User ID");
          return;
      }
      setActionLoading(prev => ({ ...prev, [`view-${targetUserId}`]: true }));
      setImageError(false); 
      setImageLoading(true);
      try {
          const res = await verificationApi.getPresignedUrl(targetUserId);
          setReviewing({ req, url: res.url, userId: targetUserId });
      } catch (e: any) {
          onNotify('error', e.message);
          setImageLoading(false);
      } finally {
          setActionLoading(prev => ({ ...prev, [`view-${targetUserId}`]: false }));
      }
  };

  const handleApproveIdentity = async (userId: string) => {
      setActionLoading(prev => ({ ...prev, 'approve_id': true }));
      try {
          const res = await verificationApi.approveIdentity(userId);
          if (res.success) {
              onNotify('success', "Identity Approved");
              setReviewing(null);
              fetchRequests();
          }
      } catch (e: any) {
          onNotify('error', e.message);
      } finally {
          setActionLoading(prev => ({ ...prev, 'approve_id': false }));
      }
  };

  const handleRejectIdentity = async (userId: string, reason: string) => {
      setActionLoading(prev => ({ ...prev, 'reject_id': true }));
      try {
          const res = await verificationApi.rejectIdentity(userId, reason);
          if (res.success) {
              onNotify('success', "Identity Rejected");
              setReviewing(null);
              setRejectModal({ isOpen: false, userId: null });
              fetchRequests();
          }
      } catch (e: any) {
          onNotify('error', e.message);
      } finally {
          setActionLoading(prev => ({ ...prev, 'reject_id': false }));
      }
  };

  return (
    <div className="space-y-6">
        <RejectModal
            isOpen={rejectModal.isOpen}
            isProcessing={actionLoading['reject_id']}
            onClose={() => setRejectModal(prev => ({ ...prev, isOpen: false }))}
            onConfirm={(reason) => {
                if (rejectModal.userId) handleRejectIdentity(rejectModal.userId, reason);
            }}
        />

        {reviewing && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center px-4">
                <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-md" onClick={() => setReviewing(null)}></div>
                <div className="relative bg-white dark:bg-slate-900 rounded-2xl w-full max-w-2xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-800">
                    <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-900">
                        <h3 className="font-bold text-lg dark:text-white flex items-center gap-2">
                            <UserIcon size={20} className="text-emerald-500" />
                            Review Identity: {reviewing.req.userEmail}
                        </h3>
                        <button onClick={() => setReviewing(null)}><X size={20} className="text-slate-500"/></button>
                    </div>
                    
                    <div className="flex-1 overflow-y-auto p-6 bg-slate-100 dark:bg-black flex items-center justify-center">
                        {imageLoading && <div className="absolute inset-0 flex items-center justify-center bg-white/50 dark:bg-black/50 z-10"><Loader2 className="animate-spin text-emerald-500" size={32}/></div>}
                        
                        {!imageError ? (
                            <img 
                                src={reviewing.url} 
                                alt="ID Document" 
                                className="max-w-full max-h-[60vh] object-contain rounded-lg shadow-lg border border-slate-200 dark:border-slate-800"
                                onLoad={() => setImageLoading(false)}
                                onError={() => { setImageError(true); setImageLoading(false); }}
                            />
                        ) : (
                            <div className="text-center p-8 text-red-500 bg-red-50 dark:bg-red-900/10 rounded-xl border border-red-200 dark:border-red-900">
                                <AlertTriangle size={48} className="mx-auto mb-2 opacity-50"/>
                                <p>Failed to load document image.</p>
                                <p className="text-xs mt-2 opacity-70">The URL may have expired or is invalid.</p>
                            </div>
                        )}
                    </div>

                    <div className="p-4 border-t border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 flex justify-between items-center">
                        <div className="text-xs text-slate-500">
                            User ID: <span className="font-mono">{reviewing.userId}</span>
                        </div>
                        <div className="flex gap-3">
                            <button 
                                onClick={() => setRejectModal({ isOpen: true, userId: reviewing.userId })}
                                disabled={actionLoading['reject_id']}
                                className="px-4 py-2 bg-red-50 text-red-600 dark:bg-red-900/20 dark:text-red-400 rounded-lg font-bold hover:bg-red-100 dark:hover:bg-red-900/30 transition-colors"
                            >
                                Reject
                            </button>
                            <button 
                                onClick={() => handleApproveIdentity(reviewing.userId)}
                                disabled={actionLoading['approve_id']}
                                className="px-6 py-2 bg-emerald-600 text-white rounded-lg font-bold hover:bg-emerald-700 transition-colors shadow-lg shadow-emerald-600/20 disabled:opacity-70 disabled:cursor-wait flex items-center gap-2"
                            >
                                {actionLoading['approve_id'] && <Loader2 size={16} className="animate-spin"/>}
                                Approve Identity
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}

        <h2 className="text-2xl font-bold text-slate-900 dark:text-white">ID Verification Requests</h2>
        {loading ? (
            <div className="flex justify-center py-12"><Loader2 className="animate-spin text-accent-600" /></div>
        ) : requests.length === 0 ? (
            <div className="text-center py-12 text-slate-500 bg-white dark:bg-slate-900 rounded-xl border border-dashed border-slate-200 dark:border-slate-800">
                No pending identity checks.
            </div>
        ) : (
            <div className="space-y-4">
                {requests.map((req, i) => (
                    <div key={i} className="bg-white dark:bg-slate-900 p-6 rounded-xl border border-slate-200 dark:border-slate-800 flex items-center justify-between">
                        <div className="flex items-center gap-4">
                            <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 flex items-center justify-center font-bold">
                                {req.userEmail?.[0].toUpperCase()}
                            </div>
                            <div>
                                <h3 className="font-bold text-slate-900 dark:text-white">{req.userEmail}</h3>
                                <p className="text-xs text-slate-500">
                                    User ID: {req.userId || (req as any)._id}
                                </p>
                            </div>
                        </div>
                        <button 
                            onClick={() => openReviewModal(req)}
                            disabled={actionLoading[`view-${req.userId || (req as any)._id}`]}
                            className="px-4 py-2 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 font-medium transition-colors flex items-center gap-2"
                        >
                            {actionLoading[`view-${req.userId || (req as any)._id}`] ? <Loader2 size={16} className="animate-spin"/> : <Eye size={16}/>}
                            Review Doc
                        </button>
                    </div>
                ))}
            </div>
        )}
    </div>
  );
};

export default AdminVerificationsSection;
