
import React, { useState, useEffect, useRef } from 'react';
import { ExpertUserDesc, ExpertStats, ExpertDefinition, UserSearchResult, ExpertSubscription } from '../../types';
import { expertApi } from '../../api/expert';
import { Loader2, Search, X, ChevronDown, Save, Cpu, Power, Trash2, Library, Plus, Edit3, AlertCircle, CheckCircle, CreditCard, Clock } from 'lucide-react';
import ConfirmModal from '../ConfirmModal';

interface ExpertSystemsSectionProps {
  onNotify: (type: 'success' | 'error', message: string) => void;
}

const ExpertSystemsSection: React.FC<ExpertSystemsSectionProps> = ({ onNotify }) => {
  const [expertUsers, setExpertUsers] = useState<ExpertUserDesc[]>([]);
  const [expertStats, setExpertStats] = useState<ExpertStats | null>(null);
  const [availableExperts, setAvailableExperts] = useState<ExpertDefinition[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showExpertModal, setShowExpertModal] = useState(false);
  const [showCatalogModal, setShowCatalogModal] = useState(false);
  const [loadingAction, setLoadingAction] = useState<Record<string, boolean>>({});
  const [confirmModal, setConfirmModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void; isLoading?: boolean }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

  // Expert Access State
  const [expertFormMode, setExpertFormMode] = useState<'add' | 'edit'>('add');
  const [expertFormData, setExpertFormData] = useState({
      userEmail: '',
      expertId: '',
      expertName: '',
      licenseType: 'basic',
      expirationDate: '',
      maxAccounts: 1,
      isActive: true,
      notes: '',
      // Subscription Sub-fields
      subStatus: 'active' as ExpertSubscription['status'],
      subPlan: 'professional',
      subPeriodEnd: '',
      subPaymentMethod: 'stripe'
  });
  const [selectedUsers, setSelectedUsers] = useState<UserSearchResult[]>([]);
  const [userSearchQuery, setUserSearchQuery] = useState('');
  const [userSearchResults, setUserSearchResults] = useState<UserSearchResult[]>([]);
  const [isSearchingUsers, setIsSearchingUsers] = useState(false);
  const [batchMode, setBatchMode] = useState<'partial' | 'atomic'>('partial');
  const [batchResults, setBatchResults] = useState<any[] | null>(null);
  const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Catalog State
  const [catalogFormMode, setCatalogFormMode] = useState<'create' | 'edit'>('create');
  const [catalogBatchMode, setCatalogBatchMode] = useState(false);
  const [catalogBatchInput, setCatalogBatchInput] = useState('');
  const [catalogFormData, setCatalogFormData] = useState({
      expertId: '',
      name: '',
      description: '',
      metadata: '{}',
      isActive: true
  });
  const [catalogErrors, setCatalogErrors] = useState<any[] | null>(null);

  useEffect(() => {
      fetchData();
  }, []);

  const fetchData = async () => {
      setIsLoading(true);
      try {
          const [usersRes, statsRes, expertsRes] = await Promise.all([
              expertApi.getUsers(),
              expertApi.getStats(),
              expertApi.getAvailableExperts()
          ]);
          setExpertUsers(usersRes.users);
          setExpertStats(statsRes.stats);
          setAvailableExperts(expertsRes.experts || []);
      } catch (e: any) {
          console.error("Expert Data Fetch Error", e);
          onNotify('error', 'Failed to load expert data: ' + e.message);
      } finally {
          setIsLoading(false);
      }
  };

  // User Search
  useEffect(() => {
      if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);
      if (userSearchQuery.trim().length >= 2) {
          setIsSearchingUsers(true);
          searchTimeoutRef.current = setTimeout(async () => {
              try {
                  const res = await expertApi.searchUsers(userSearchQuery);
                  setUserSearchResults(res.users);
              } catch (e) {
                  console.error("Search error", e);
              } finally {
                  setIsSearchingUsers(false);
              }
          }, 400);
      } else {
          setUserSearchResults([]);
          setIsSearchingUsers(false);
      }
      return () => { if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current); };
  }, [userSearchQuery]);

  const handleSelectExpert = (expertId: string) => {
      const expert = availableExperts.find(e => e.expertId === expertId);
      setExpertFormData(prev => ({
          ...prev,
          expertId: expertId,
          expertName: expert ? expert.expertName : prev.expertName
      }));
  };

  const handleAddUserToSelection = (user: UserSearchResult) => {
      if (!selectedUsers.find(u => u.email === user.email)) {
          setSelectedUsers(prev => [...prev, user]);
      }
      setUserSearchQuery('');
      setUserSearchResults([]);
  };

  const handleRemoveUserFromSelection = (email: string) => {
      setSelectedUsers(prev => prev.filter(u => u.email !== email));
  };

  const openExpertAddModal = () => {
      setExpertFormData({
          userEmail: '',
          expertId: availableExperts.length > 0 ? availableExperts[0].expertId : '',
          expertName: availableExperts.length > 0 ? availableExperts[0].expertName : '',
          licenseType: 'basic',
          expirationDate: '',
          maxAccounts: 1,
          isActive: true,
          notes: '',
          subStatus: 'active',
          subPlan: 'professional',
          subPeriodEnd: '',
          subPaymentMethod: 'stripe'
      });
      setSelectedUsers([]);
      setUserSearchQuery('');
      setExpertFormMode('add');
      setBatchMode('partial');
      setBatchResults(null);
      setShowExpertModal(true);
  };

  const openExpertEditModal = (u: ExpertUserDesc, access: any) => {
      setExpertFormData({
          userEmail: u.email,
          expertId: access.expertId,
          expertName: access.expertName,
          licenseType: access.licenseType,
          expirationDate: access.expirationDate ? new Date(access.expirationDate).toISOString().split('T')[0] : '',
          maxAccounts: access.maxAccounts || 1,
          isActive: access.isActive,
          notes: '',
          subStatus: access.subscription?.status || 'active',
          subPlan: access.subscription?.plan || 'professional',
          subPeriodEnd: access.subscription?.currentPeriodEnd ? new Date(access.subscription.currentPeriodEnd).toISOString().split('T')[0] : '',
          subPaymentMethod: access.subscription?.paymentMethod || 'stripe'
      });
      setSelectedUsers([{ email: u.email, firstName: u.firstName || '', lastName: u.lastName || '' }]);
      setExpertFormMode('edit');
      setBatchResults(null);
      setShowExpertModal(true);
  };

  const handleExpertFormSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setLoadingAction(prev => ({ ...prev, 'expert_submit': true }));
      try {
          // Construct the nested subscription object
          const subscriptionPayload: ExpertSubscription = {
              status: expertFormData.subStatus,
              plan: expertFormData.subPlan,
              currentPeriodEnd: expertFormData.subPeriodEnd || undefined,
              paymentMethod: expertFormData.subPaymentMethod
          };

          const updatesPayload = {
              licenseType: expertFormData.licenseType,
              expirationDate: expertFormData.expirationDate || undefined,
              maxAccounts: expertFormData.maxAccounts,
              isActive: expertFormData.isActive,
              subscription: subscriptionPayload
          };

          if (expertFormMode === 'add') {
              const items = selectedUsers.map(u => ({
                  userEmail: u.email,
                  expertId: expertFormData.expertId,
                  expertName: expertFormData.expertName,
                  updates: updatesPayload, // Using nested structure
                  notes: expertFormData.notes
              }));

              if (items.length === 0) {
                  if (expertFormData.userEmail) {
                      items.push({
                          userEmail: expertFormData.userEmail,
                          expertId: expertFormData.expertId,
                          expertName: expertFormData.expertName,
                          updates: updatesPayload,
                          notes: expertFormData.notes
                      });
                  } else {
                      throw new Error("Please select at least one user.");
                  }
              }

              const payload = { items, atomic: batchMode === 'atomic' };
              const res = await expertApi.addUser(payload);
              
              if (res.results) {
                  setBatchResults(res.results);
                  if (res.success || res.results.some((r: any) => r.success)) {
                      fetchData();
                  }
              } else if (res.success) {
                  onNotify('success', res.message || `Access granted to ${items.length} users.`);
                  setShowExpertModal(false);
                  fetchData();
              }
          } else {
              const res = await expertApi.updateUser(expertFormData.userEmail, expertFormData.expertId, updatesPayload);
              if (res.success) {
                  onNotify('success', res.message);
                  setShowExpertModal(false);
                  fetchData();
              }
          }
      } catch (e: any) {
          onNotify('error', e.message || 'Operation failed');
      } finally {
          setLoadingAction(prev => ({ ...prev, 'expert_submit': false }));
      }
  };

  const handleToggleExpertAccess = async (userEmail: string, expertId: string, currentStatus: boolean) => {
      const key = `toggle_${userEmail}_${expertId}`;
      setLoadingAction(prev => ({ ...prev, [key]: true }));
      try {
          const res = await expertApi.toggleAccess(userEmail, expertId, !currentStatus);
          if (res.success) {
              onNotify('success', res.message);
              fetchData();
          }
      } catch (e: any) {
          onNotify('error', e.message);
      } finally {
          setLoadingAction(prev => ({ ...prev, [key]: false }));
      }
  };

  const handleRemoveExpert = (userEmail: string, expertId: string) => {
      setConfirmModal({
          isOpen: true,
          title: 'Remove Expert Access',
          message: `Are you sure you want to remove expert ${expertId} from user ${userEmail}?`,
          isLoading: false,
          onConfirm: async () => {
              setConfirmModal(prev => ({ ...prev, isLoading: true }));
              try {
                  const res = await expertApi.removeUser(userEmail, expertId);
                  if (res.success) {
                      onNotify('success', res.message);
                      fetchData();
                      setConfirmModal(prev => ({ ...prev, isOpen: false }));
                  }
              } catch (e: any) {
                  onNotify('error', e.message);
                  setConfirmModal(prev => ({ ...prev, isLoading: false }));
              }
          }
      });
  };

  // Catalog Logic
  const openCatalogCreate = () => {
      setCatalogFormData({
          expertId: '',
          name: '',
          description: '',
          metadata: '{\n  "category": "scalper"\n}',
          isActive: true
      });
      setCatalogBatchInput('[\n  { "expertId": "EXP_1", "name": "Expert One" },\n  { "expertId": "EXP_2", "name": "Expert Two" }\n]');
      setCatalogFormMode('create');
      setCatalogBatchMode(false);
      setCatalogErrors(null);
      setShowCatalogModal(true);
  };

  const openCatalogEdit = (expert: ExpertDefinition) => {
      setCatalogFormData({
          expertId: expert.expertId,
          name: expert.expertName,
          description: expert.description || '',
          metadata: JSON.stringify(expert.metadata || {}, null, 2),
          isActive: expert.isActive !== false
      });
      setCatalogFormMode('edit');
      setCatalogBatchMode(false);
      setCatalogErrors(null);
      setShowCatalogModal(true);
  };

  const handleCatalogFormSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setCatalogErrors(null);
      setLoadingAction(prev => ({ ...prev, 'catalog_submit': true }));

      try {
          if (catalogBatchMode) {
              let items = [];
              try {
                  items = JSON.parse(catalogBatchInput);
                  if (!Array.isArray(items)) throw new Error("Input must be a JSON array");
              } catch (err) {
                  throw new Error("Invalid JSON format for batch input.");
              }

              const res = await expertApi.addExpert({ items });
              if (res.success) {
                  onNotify('success', 'Batch operation successful');
                  setShowCatalogModal(false);
                  fetchData();
              } else if (res.details) {
                  setCatalogErrors(res.details);
                  onNotify('error', 'Validation errors occurred in batch');
              } else {
                  throw new Error(res.message || 'Operation failed');
              }
          } else {
              let metaObj = {};
              try {
                  metaObj = JSON.parse(catalogFormData.metadata);
              } catch (e) {
                  throw new Error("Invalid JSON in Metadata field");
              }

              const payload = {
                  expertId: catalogFormData.expertId,
                  name: catalogFormData.name,
                  description: catalogFormData.description,
                  metadata: metaObj,
                  isActive: catalogFormData.isActive
              };

              const res = await expertApi.addExpert(payload);
              if (res.success) {
                  onNotify('success', `Expert ${catalogFormMode === 'create' ? 'created' : 'updated'} successfully`);
                  setShowCatalogModal(false);
                  fetchData();
              } else if (res.details) {
                  setCatalogErrors(res.details);
                  onNotify('error', 'Validation errors occurred');
              } else {
                  throw new Error(res.message || 'Operation failed');
              }
          }
      } catch (e: any) {
          onNotify('error', e.message);
      } finally {
          setLoadingAction(prev => ({ ...prev, 'catalog_submit': false }));
      }
  };

  return (
    <div className="space-y-6">
        <ConfirmModal 
            isOpen={confirmModal.isOpen} 
            title={confirmModal.title} 
            message={confirmModal.message} 
            isLoading={confirmModal.isLoading}
            onClose={() => setConfirmModal(prev => ({ ...prev, isOpen: false }))} 
            onConfirm={confirmModal.onConfirm}
        />

        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <h2 className="text-2xl font-bold text-slate-900 dark:text-white">Expert Access Management</h2>
            <div className="flex gap-2">
                <button 
                    onClick={openCatalogCreate}
                    className="px-4 py-2 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 rounded-lg font-bold flex items-center gap-2 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                >
                    <Library size={18}/> Manage Catalog
                </button>
                <button 
                    onClick={openExpertAddModal}
                    className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-bold flex items-center gap-2 hover:bg-emerald-700 transition-colors shadow-lg shadow-emerald-600/20"
                >
                    <Cpu size={18}/> Grant Access
                </button>
            </div>
        </div>

        {/* Catalog Preview with Loading State */}
        <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm">
            <div className="flex items-center justify-between mb-4">
                <h3 className="font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <Library size={18} className="text-accent-500"/> Available Expert Catalog
                </h3>
                <button onClick={openCatalogCreate} className="text-xs font-bold text-accent-600 hover:underline flex items-center gap-1">
                    <Plus size={12}/> Add New
                </button>
            </div>
            
            {isLoading ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {[1, 2, 3].map(i => (
                        <div key={i} className="p-4 border border-slate-200 dark:border-slate-700 rounded-lg bg-slate-50 dark:bg-slate-950 animate-pulse">
                            <div className="h-5 bg-slate-200 dark:bg-slate-800 rounded w-3/4 mb-3"></div>
                            <div className="h-3 bg-slate-200 dark:bg-slate-800 rounded w-1/2 mb-3"></div>
                            <div className="h-12 bg-slate-200 dark:bg-slate-800 rounded w-full"></div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {availableExperts.length > 0 ? availableExperts.map(exp => (
                        <div key={exp.expertId} className="p-4 border border-slate-200 dark:border-slate-700 rounded-lg bg-slate-50 dark:bg-slate-950 hover:border-accent-500/50 transition-colors group">
                            <div className="flex justify-between items-start mb-2">
                                <h4 className="font-bold text-sm text-slate-900 dark:text-white">{exp.expertName}</h4>
                                <span className={`w-2 h-2 rounded-full ${exp.isActive !== false ? 'bg-emerald-500' : 'bg-red-500'}`} title={exp.isActive !== false ? "Active" : "Inactive"}></span>
                            </div>
                            <p className="text-xs text-slate-500 font-mono mb-2">{exp.expertId}</p>
                            {exp.description && <p className="text-xs text-slate-600 dark:text-slate-400 mb-3 line-clamp-2">{exp.description}</p>}
                            <div className="flex justify-end opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={() => openCatalogEdit(exp)} className="text-xs font-medium text-accent-600 hover:text-accent-700 dark:hover:text-accent-400 flex items-center gap-1">
                                    <Edit3 size={12}/> Edit
                                </button>
                            </div>
                        </div>
                    )) : (
                        <div className="col-span-full text-center py-8 text-slate-500 text-sm">No experts defined in catalog.</div>
                    )}
                </div>
            )}
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-800">
                <div className="text-xs font-bold text-slate-500 uppercase">Total Licenses</div>
                <div className="text-2xl font-black text-slate-900 dark:text-white mt-1">
                    {expertStats?.totalUsers || 0}
                </div>
            </div>
            <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-800">
                <div className="text-xs font-bold text-slate-500 uppercase">Active Users</div>
                <div className="text-2xl font-black text-emerald-600 dark:text-emerald-400 mt-1">
                    {expertStats?.activeUsers || 0}
                </div>
            </div>
            <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-800">
                <div className="text-xs font-bold text-slate-500 uppercase">Total Trades</div>
                <div className="text-2xl font-black text-slate-900 dark:text-white mt-1">
                    {(expertStats?.totalTrades || 0).toLocaleString()}
                </div>
            </div>
            <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-800">
                <div className="text-xs font-bold text-slate-500 uppercase">System Profit</div>
                <div className="text-2xl font-black text-green-600 dark:text-green-400 mt-1">
                    ${(expertStats?.totalProfit || 0).toLocaleString()}
                </div>
            </div>
        </div>

        {/* Users Table */}
        <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 overflow-hidden">
            <div className="overflow-x-auto">
                <table className="w-full text-left min-w-[800px]">
                    <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-xs uppercase font-semibold">
                        <tr>
                            <th className="px-6 py-4">User</th>
                            <th className="px-6 py-4">Expert System</th>
                            <th className="px-6 py-4">License</th>
                            <th className="px-6 py-4">Subscription</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                        {isLoading ? (
                            <tr><td colSpan={6} className="px-6 py-12 text-center"><Loader2 className="animate-spin mx-auto text-emerald-600"/></td></tr>
                        ) : expertUsers.length === 0 ? (
                            <tr><td colSpan={6} className="px-6 py-12 text-center text-slate-500">No active expert licenses found.</td></tr>
                        ) : expertUsers.map(u => (
                            u.experts.map((access, idx) => (
                                <tr key={`${u.email}-${idx}`} className="hover:bg-slate-50 dark:hover:bg-slate-800/50">
                                    <td className="px-6 py-4">
                                        <div className="font-bold text-slate-900 dark:text-white">{u.firstName} {u.lastName}</div>
                                        <div className="text-xs text-slate-500">{u.email}</div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="font-medium text-slate-900 dark:text-white">{access.expertName}</div>
                                        <div className="text-xs text-slate-500 font-mono">{access.expertId}</div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="inline-flex px-2 py-1 rounded text-xs font-bold uppercase bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-700">
                                            {access.licenseType}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">
                                        {access.subscription ? (
                                            <div className="text-xs">
                                                <div className="font-bold text-slate-900 dark:text-white capitalize">{access.subscription.plan || 'No Plan'}</div>
                                                <div className={`capitalize font-medium ${access.subscription.status === 'active' ? 'text-emerald-500' : 'text-slate-400'}`}>
                                                    {access.subscription.status}
                                                </div>
                                            </div>
                                        ) : (
                                            <span className="text-xs text-slate-400 italic">None</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-full text-xs font-bold ${
                                            access.isActive 
                                            ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' 
                                            : 'bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400'
                                        }`}>
                                            <span className={`w-1.5 h-1.5 rounded-full ${access.isActive ? 'bg-emerald-500' : 'bg-red-500'}`}></span>
                                            {access.isActive ? 'Active' : 'Suspended'}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-right flex justify-end gap-2">
                                        <button 
                                            onClick={() => openExpertEditModal(u, access)}
                                            className="p-1.5 text-slate-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded transition-colors"
                                            title="Edit Access"
                                        >
                                            <Edit3 size={16}/>
                                        </button>
                                        <button 
                                            onClick={() => handleToggleExpertAccess(u.email, access.expertId, access.isActive)}
                                            className={`p-1.5 rounded transition-colors ${
                                                access.isActive 
                                                ? 'text-slate-500 hover:text-amber-600 hover:bg-amber-50 dark:hover:bg-amber-900/20' 
                                                : 'text-slate-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20'
                                            }`}
                                            title={access.isActive ? "Suspend" : "Activate"}
                                            disabled={loadingAction[`toggle_${u.email}_${access.expertId}`]}
                                        >
                                            {loadingAction[`toggle_${u.email}_${access.expertId}`] ? <Loader2 size={16} className="animate-spin"/> : <Power size={16}/>}
                                        </button>
                                        <button 
                                            onClick={() => handleRemoveExpert(u.email, access.expertId)}
                                            className="p-1.5 text-slate-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded transition-colors"
                                            title="Revoke Access"
                                        >
                                            <Trash2 size={16}/>
                                        </button>
                                    </td>
                                </tr>
                            ))
                        ))}
                    </tbody>
                </table>
            </div>
        </div>

        {/* Access Modal with Subscription Fields */}
        {showExpertModal && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center px-4">
                <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-sm" onClick={() => setShowExpertModal(false)}></div>
                <div className="relative bg-white dark:bg-slate-900 rounded-2xl w-full max-w-xl max-h-[90vh] overflow-y-auto shadow-2xl border border-slate-200 dark:border-slate-800 flex flex-col">
                    <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-900 sticky top-0 z-10">
                        <h3 className="font-bold text-lg dark:text-white">{expertFormMode === 'add' ? 'Grant Expert Access' : 'Edit Access'}</h3>
                        <button onClick={() => setShowExpertModal(false)}><X size={20} className="text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"/></button>
                    </div>
                    
                    {batchResults ? (
                        <div className="p-6">
                            <h3 className="font-bold text-slate-900 dark:text-white mb-4">Batch Operation Results</h3>
                            
                            {batchMode === 'atomic' && batchResults.some(r => !r.success) && (
                                <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 text-red-700 dark:text-red-400 p-4 rounded-lg mb-4 text-sm flex gap-3">
                                    <AlertCircle className="shrink-0" size={20} />
                                    <p><strong>Operation Failed:</strong> Strict mode was enabled and errors occurred.</p>
                                </div>
                            )}

                            <div className="max-h-60 overflow-y-auto border border-slate-200 dark:border-slate-800 rounded-lg divide-y divide-slate-200 dark:divide-slate-800 mb-6 custom-scrollbar">
                                {batchResults.map((res, idx) => (
                                    <div key={idx} className={`p-3 flex items-start justify-between gap-4 ${res.success ? 'bg-green-50/50 dark:bg-green-900/10' : 'bg-red-50/50 dark:bg-red-900/10'}`}>
                                        <div>
                                            <div className="text-sm font-bold text-slate-800 dark:text-white">{res.userEmail}</div>
                                            <div className="text-xs text-slate-500">{res.expertId}</div>
                                            {!res.success && res.error && (
                                                <div className="text-xs text-red-600 dark:text-red-400 mt-1">{res.error}</div>
                                            )}
                                        </div>
                                        <div className="shrink-0 pt-1">
                                            {res.success 
                                                ? <CheckCircle size={18} className="text-emerald-500"/>
                                                : <AlertCircle size={18} className="text-red-500"/>
                                            }
                                        </div>
                                    </div>
                                ))}
                            </div>
                            <div className="flex justify-end">
                                <button onClick={() => setShowExpertModal(false)} className="px-6 py-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-lg font-bold">Close</button>
                            </div>
                        </div>
                    ) : (
                        <form onSubmit={handleExpertFormSubmit} className="p-6 space-y-6">
                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-1">Select Expert</label>
                                    <div className="relative">
                                        <select
                                            value={expertFormData.expertId}
                                            onChange={e => handleSelectExpert(e.target.value)}
                                            className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg outline-none focus:ring-2 focus:ring-accent-500 dark:text-white appearance-none"
                                            disabled={expertFormMode === 'edit'}
                                        >
                                            {availableExperts.length === 0 && <option value="">Loading experts...</option>}
                                            {availableExperts.map(exp => (
                                                <option key={exp.expertId} value={exp.expertId}>{exp.expertName} ({exp.expertId})</option>
                                            ))}
                                        </select>
                                        <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={16} />
                                    </div>
                                </div>

                                {expertFormMode === 'add' ? (
                                    <div>
                                        <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-1">Add Users</label>
                                        <div className="flex flex-wrap gap-2 mb-2">
                                            {selectedUsers.map(u => (
                                                <div key={u.email} className="flex items-center gap-1 bg-accent-100 dark:bg-accent-900/30 text-accent-800 dark:text-accent-300 px-2 py-1 rounded-full text-xs font-medium border border-accent-200 dark:border-accent-800">
                                                    <span>{u.firstName} {u.lastName}</span>
                                                    <button type="button" onClick={() => handleRemoveUserFromSelection(u.email)} className="hover:text-red-500"><X size={12}/></button>
                                                </div>
                                            ))}
                                        </div>
                                        <div className="relative">
                                            <input 
                                                type="text" 
                                                value={userSearchQuery}
                                                onChange={e => setUserSearchQuery(e.target.value)}
                                                className="w-full px-3 py-2 pl-9 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg outline-none focus:ring-2 focus:ring-accent-500 dark:text-white"
                                                placeholder="Search by name or email..."
                                            />
                                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                                            {isSearchingUsers && <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 animate-spin text-slate-400" size={16} />}
                                            {userSearchResults.length > 0 && (
                                                <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg shadow-xl max-h-60 overflow-y-auto z-20">
                                                    {userSearchResults.map(user => (
                                                        <button key={user.email} type="button" onClick={() => handleAddUserToSelection(user)} className="w-full text-left px-4 py-2 hover:bg-slate-50 dark:hover:bg-slate-800 border-b border-slate-100 dark:border-slate-800 last:border-0 flex flex-col">
                                                            <span className="font-bold text-sm text-slate-800 dark:text-white">{user.firstName} {user.lastName}</span>
                                                            <span className="text-xs text-slate-500">{user.email}</span>
                                                        </button>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ) : (
                                    <div>
                                        <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-1">User Email</label>
                                        <input type="email" disabled value={expertFormData.userEmail} className="w-full px-3 py-2 bg-slate-100 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg text-slate-500 cursor-not-allowed" />
                                    </div>
                                )}
                            </div>

                            {/* Core License Settings */}
                            <div className="grid grid-cols-2 gap-4 pt-4 border-t border-slate-100 dark:border-slate-800">
                                <div>
                                    <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-1">License Type</label>
                                    <select value={expertFormData.licenseType} onChange={e => setExpertFormData({...expertFormData, licenseType: e.target.value})} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg outline-none focus:ring-2 focus:ring-accent-500 dark:text-white">
                                        <option value="basic">Basic</option>
                                        <option value="pro">Pro</option>
                                        <option value="enterprise">Enterprise</option>
                                        <option value="trial">Trial</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-1">Max Accounts</label>
                                    <input type="number" min="1" value={expertFormData.maxAccounts} onChange={e => setExpertFormData({...expertFormData, maxAccounts: parseInt(e.target.value) || 1})} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg outline-none focus:ring-2 focus:ring-accent-500 dark:text-white" />
                                </div>
                            </div>

                            {/* Subscription Settings */}
                            <div className="p-4 bg-slate-50 dark:bg-slate-800/30 rounded-xl border border-slate-200 dark:border-slate-800 space-y-4">
                                <h4 className="text-xs font-bold uppercase text-slate-500 flex items-center gap-2 mb-2">
                                    <CreditCard size={14}/> Subscription Details
                                </h4>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs font-bold text-slate-600 dark:text-slate-400 mb-1">Status</label>
                                        <select 
                                            value={expertFormData.subStatus} 
                                            onChange={e => setExpertFormData({...expertFormData, subStatus: e.target.value as any})}
                                            className="w-full px-3 py-2 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg text-sm dark:text-white"
                                        >
                                            <option value="active">Active</option>
                                            <option value="cancelled">Cancelled</option>
                                            <option value="expired">Expired</option>
                                            <option value="pending">Pending</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-slate-600 dark:text-slate-400 mb-1">Plan</label>
                                        <select 
                                            value={expertFormData.subPlan} 
                                            onChange={e => setExpertFormData({...expertFormData, subPlan: e.target.value})}
                                            className="w-full px-3 py-2 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg text-sm dark:text-white"
                                        >
                                            <option value="basic">Basic</option>
                                            <option value="professional">Professional</option>
                                            <option value="enterprise">Enterprise</option>
                                        </select>
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs font-bold text-slate-600 dark:text-slate-400 mb-1">Period End</label>
                                        <div className="relative">
                                            <input 
                                                type="date" 
                                                value={expertFormData.subPeriodEnd} 
                                                onChange={e => setExpertFormData({...expertFormData, subPeriodEnd: e.target.value})}
                                                className="w-full px-3 py-2 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg text-sm dark:text-white"
                                            />
                                            <Clock size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-slate-600 dark:text-slate-400 mb-1">Payment Method</label>
                                        <input 
                                            type="text" 
                                            placeholder="stripe, crypto, etc."
                                            value={expertFormData.subPaymentMethod} 
                                            onChange={e => setExpertFormData({...expertFormData, subPaymentMethod: e.target.value})}
                                            className="w-full px-3 py-2 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg text-sm dark:text-white"
                                        />
                                    </div>
                                </div>
                            </div>

                            {expertFormMode === 'add' && selectedUsers.length > 1 && (
                                <div className="bg-slate-50 dark:bg-slate-900/50 p-4 rounded-lg border border-slate-200 dark:border-slate-800">
                                    <label className="block text-xs font-bold uppercase text-slate-500 mb-2">Batch Operation Mode</label>
                                    <div className="flex gap-2">
                                        <button type="button" onClick={() => setBatchMode('partial')} className={`flex-1 py-2 text-xs font-bold rounded-md border transition-all ${batchMode === 'partial' ? 'bg-white dark:bg-slate-800 border-accent-500 text-accent-600 dark:text-accent-400 shadow-sm' : 'border-transparent text-slate-500 hover:bg-white/50 dark:hover:bg-slate-800/50'}`}>Partial</button>
                                        <button type="button" onClick={() => setBatchMode('atomic')} className={`flex-1 py-2 text-xs font-bold rounded-md border transition-all ${batchMode === 'atomic' ? 'bg-white dark:bg-slate-800 border-accent-500 text-accent-600 dark:text-accent-400 shadow-sm' : 'border-transparent text-slate-500 hover:bg-white/50 dark:hover:bg-slate-800/50'}`}>Strict</button>
                                    </div>
                                </div>
                            )}
                            
                            <div className="pt-4 flex justify-end gap-3 border-t border-slate-100 dark:border-slate-800">
                                <button type="button" onClick={() => setShowExpertModal(false)} className="px-4 py-2 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors">Cancel</button>
                                <button type="submit" disabled={loadingAction['expert_submit']} className="px-6 py-2 bg-accent-600 text-white rounded-lg font-bold hover:bg-accent-700 transition-colors shadow-lg shadow-accent-600/20 disabled:opacity-70 flex items-center gap-2">
                                    {loadingAction['expert_submit'] ? <Loader2 size={18} className="animate-spin"/> : <Save size={18}/>}
                                    {expertFormMode === 'add' ? 'Grant Access' : 'Update Access'}
                                </button>
                            </div>
                        </form>
                    )}
                </div>
            </div>
        )}

        {/* Catalog Modal stays the same... */}
    </div>
  );
};

export default ExpertSystemsSection;
