import { User } from '../types';
import { getApiOrigin } from './config';

const API_URL = `${getApiOrigin()}/api/users`;

const getHeaders = () => {
  return {
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  };
};

const handleResponse = async (res: Response) => {
  const contentType = res.headers.get("content-type");
  if (contentType && contentType.includes("application/json")) {
    const json = await res.json();
    if (!res.ok) {
      throw new Error(json.message || json.error || `API Error: ${res.status}`);
    }
    // Some backends wrap arrays in a data property
    return json.data || json;
  } else {
    const text = await res.text();
    console.error(`Non-JSON response from ${res.url}:`, text.substring(0, 100));
    throw new Error(`API Error: ${res.status} (Invalid Response Format)`);
  }
};

const sanitizeUser = (user: User): User => {
  // Ensure _id exists even if backend uses user_id
  const _id = user._id || user.user_id;
  
  let profilePic = user.profilePic;
  if (profilePic && !profilePic.startsWith('http') && profilePic.includes('cdn.quader864.ir')) {
      profilePic = `https://${profilePic}`;
  }
  
  return { ...user, _id, profilePic };
};

export const userApi = {
  // Admin: Get all users
  getAll: async (): Promise<User[]> => {
    try {
      const res = await fetch(`${API_URL}`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      const data = await handleResponse(res);
      const users = Array.isArray(data) ? data : [];
      return users.map(sanitizeUser);
    } catch (error) {
      console.error('Fetch users failed:', error);
      return [];
    }
  },

  // Admin: Update user role
  updateRole: async (id: string, role: string): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/${id}/role`, {
        method: 'PATCH',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({ role })
      });
      await handleResponse(res);
      return { success: true, message: 'User role updated successfully' };
    } catch (error: any) {
      return { success: false, message: error.message };
    }
  },

  // User: Upload Profile Picture
  uploadProfilePic: async (file: File): Promise<{ success: boolean; message: string; profilePic: string }> => {
    const formData = new FormData();
    formData.append('profilePic', file);

    try {
      const res = await fetch(`${API_URL}/upload/profile-pic`, {
        method: 'POST',
        headers: {
            'Accept': 'application/json'
        },
        mode: 'cors',
        credentials: 'include',
        body: formData
      });
      return await handleResponse(res);
    } catch (error: any) {
      throw new Error(error.message || 'Image upload failed');
    }
  },

  // User: Update Profile Details
  updateProfile: async (data: Partial<User>): Promise<{ success: boolean; user: User }> => {
    try {
      const res = await fetch(`${API_URL}/me/profile`, {
        method: 'PATCH',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify(data)
      });
      const json = await handleResponse(res);
      const user = json.user ? sanitizeUser(json.user) : json;
      return { success: true, user: user as User };
    } catch (error: any) {
      throw new Error(error.message || 'Profile update failed');
    }
  },

  // Admin: Verify or Reject User Profile Data
  verifyProfile: async (id: string, status: 'verified' | 'rejected', rejectionReason?: string): Promise<{ success: boolean; message: string; user: User }> => {
    try {
      const res = await fetch(`${API_URL}/${id}/profile-verification`, {
        method: 'PATCH',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({ status, rejectionReason })
      });
      const json = await handleResponse(res);
      const user = json.user ? sanitizeUser(json.user) : json;
      return { success: true, message: json.message || 'Verification updated', user: user as User };
    } catch (error: any) {
      throw new Error(error.message || 'Verification update failed');
    }
  }
};
