
import React, { useState, useEffect } from 'react';
import { VerificationState, VerificationStatus } from '../../types';
import { verificationApi } from '../../api/verification';
import { CheckCircle, Clock, Loader2, Upload, Check, AlertTriangle } from 'lucide-react';

interface VerificationSectionProps {
  onNotify: (type: 'success' | 'error', message: string) => void;
}

const VerificationSection: React.FC<VerificationSectionProps> = ({ onNotify }) => {
  const [state, setState] = useState<VerificationState | null>(null);
  const [loading, setLoading] = useState(false);
  const [otpSent, setOtpSent] = useState(false);
  const [otpCode, setOtpCode] = useState('');
  const [uploadFile, setUploadFile] = useState<File | null>(null);
  const [actionLoading, setActionLoading] = useState<Record<string, boolean>>({});

  useEffect(() => {
      const fetchStatus = async () => {
          setLoading(true);
          try {
              const status = await verificationApi.getStatus();
              setState(status);
          } catch (e) {
              console.error(e);
          } finally {
              setLoading(false);
          }
      };
      fetchStatus();
  }, []);

  const handleSendOtp = async () => {
      setActionLoading(prev => ({ ...prev, 'otp': true }));
      try {
          const res = await verificationApi.sendEmailOtp();
          if(res.success) {
              setOtpSent(true);
              onNotify('success', res.message);
          }
      } catch (e: any) {
          onNotify('error', e.message);
      } finally {
          setActionLoading(prev => ({ ...prev, 'otp': false }));
      }
  };

  const handleConfirmOtp = async () => {
      setActionLoading(prev => ({ ...prev, 'otp_confirm': true }));
      try {
          const res = await verificationApi.confirmEmailOtp(otpCode);
          if(res.success) {
              onNotify('success', res.message);
              const status = await verificationApi.getStatus();
              setState(status);
              setOtpSent(false);
              setOtpCode('');
          }
      } catch (e: any) {
          onNotify('error', e.message);
      } finally {
          setActionLoading(prev => ({ ...prev, 'otp_confirm': false }));
      }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          if (file.size > 5 * 1024 * 1024) {
              onNotify('error', "File size exceeds 5MB limit.");
              return;
          }
          if (!['image/jpeg', 'image/png'].includes(file.type)) {
              onNotify('error', "Only JPG and PNG allowed.");
              return;
          }
          setUploadFile(file);
      }
  };

  const handleUploadIdentity = async () => {
      if (!uploadFile) return;
      setActionLoading(prev => ({ ...prev, 'upload': true }));
      try {
          const res = await verificationApi.uploadIdentity(uploadFile);
          if(res.success) {
              onNotify('success', res.message);
              setUploadFile(null);
              const status = await verificationApi.getStatus();
              setState(status);
          }
      } catch (e: any) {
          onNotify('error', e.message);
      } finally {
          setActionLoading(prev => ({ ...prev, 'upload': false }));
      }
  };

  if (loading) return <div className="flex justify-center py-12"><Loader2 className="animate-spin" /></div>;

  return (
    <div className="space-y-8">
        <h2 className="text-2xl font-bold text-slate-900 dark:text-white">Account Verification</h2>
        
        {/* Step 1: Email */}
        <div className={`bg-white dark:bg-slate-900 p-6 rounded-xl border ${state?.emailVerified ? 'border-green-200 dark:border-green-900/50' : 'border-slate-200 dark:border-slate-800'} relative overflow-hidden`}>
            {state?.emailVerified && (
                <div className="absolute top-0 right-0 p-4">
                    <CheckCircle className="text-green-500" size={24} />
                </div>
            )}
            <h3 className="font-bold text-lg mb-2 dark:text-white">Level 1: Email Verification</h3>
            <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">Required for basic commenting and posting.</p>
            
            {state?.emailVerified ? (
                <span className="inline-flex items-center gap-2 px-3 py-1 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 rounded-full text-sm font-bold">
                    <CheckCircle size={16} /> Verified
                </span>
            ) : (
                <div className="space-y-4 max-w-sm">
                    {!otpSent ? (
                        <button 
                            onClick={handleSendOtp} 
                            disabled={actionLoading['otp']}
                            className="px-4 py-2 bg-accent-600 text-white rounded-lg hover:bg-accent-700 transition-colors disabled:opacity-50"
                        >
                            {actionLoading['otp'] ? <Loader2 className="animate-spin"/> : 'Send Verification Code'}
                        </button>
                    ) : (
                        <div className="flex gap-2">
                            <input 
                                type="text" 
                                placeholder="Enter OTP" 
                                className="flex-1 px-4 py-2 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-lg outline-none"
                                value={otpCode}
                                onChange={(e) => setOtpCode(e.target.value)}
                            />
                            <button 
                                onClick={handleConfirmOtp}
                                disabled={actionLoading['otp_confirm']}
                                className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors disabled:opacity-50"
                            >
                                {actionLoading['otp_confirm'] ? <Loader2 className="animate-spin"/> : 'Confirm'}
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>

        {/* Step 2: Identity */}
        <div className={`bg-white dark:bg-slate-900 p-6 rounded-xl border ${state?.identityVerified ? 'border-green-200 dark:border-green-900/50' : 'border-slate-200 dark:border-slate-800'} relative overflow-hidden`}>
            {state?.identityVerified && (
                <div className="absolute top-0 right-0 p-4">
                    <CheckCircle className="text-green-500" size={24} />
                </div>
            )}
            
            <div className="mb-4">
                <h3 className="font-bold text-lg dark:text-white">Level 2: Identity Verification</h3>
                <p className="text-sm text-slate-500 dark:text-slate-400">Required for advanced features and badge.</p>
            </div>

            {state?.identityVerified ? (
                <span className="inline-flex items-center gap-2 px-3 py-1 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 rounded-full text-sm font-bold">
                    <CheckCircle size={16} /> Verified
                </span>
            ) : state?.identityStatus === 'pending' ? (
                <div className="flex flex-col gap-4">
                    <div className="p-4 bg-yellow-50 dark:bg-yellow-900/10 border border-yellow-100 dark:border-yellow-900/30 rounded-lg text-yellow-800 dark:text-yellow-400 flex items-start gap-3">
                        <Clock className="shrink-0 mt-0.5" size={20} />
                        <div>
                            <p className="font-bold text-sm">Under Review</p>
                            <p className="text-xs mt-1 opacity-90">Your document has been uploaded and is waiting for administrator approval.</p>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="space-y-4 max-w-sm">
                    {state?.rejectionReason && (
                        <div className="p-4 bg-red-50 dark:bg-red-900/10 border border-red-200 dark:border-red-900/30 rounded-lg text-red-800 dark:text-red-400 mb-4">
                            <p className="font-bold text-sm flex items-center gap-2"><AlertTriangle size={16}/> Application Rejected</p>
                            <p className="text-xs mt-1">Reason: {state.rejectionReason}</p>
                        </div>
                    )}

                    <div className="border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-xl p-6 text-center hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors relative">
                        <input 
                            type="file" 
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                            accept="image/jpeg,image/png"
                            onChange={handleFileSelect}
                        />
                        <Upload className="mx-auto text-slate-400 mb-2" size={24} />
                        <p className="text-sm font-medium text-slate-600 dark:text-slate-300">
                            {uploadFile ? uploadFile.name : "Click to upload ID (JPG/PNG)"}
                        </p>
                        <p className="text-xs text-slate-400 mt-1">Max 5MB</p>
                    </div>

                    {uploadFile && (
                        <button 
                            onClick={handleUploadIdentity}
                            disabled={actionLoading['upload']}
                            className="w-full px-4 py-2 bg-accent-600 text-white rounded-lg hover:bg-accent-700 transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                        >
                            {actionLoading['upload'] ? <Loader2 className="animate-spin" size={18}/> : <><Check size={18}/> Submit Document</>}
                        </button>
                    )}
                </div>
            )}
        </div>
    </div>
  );
};

export default VerificationSection;
