
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Shield, CheckCircle, Clock, FileText, ArrowLeft, Loader2, AlertCircle } from 'lucide-react';
import { User, VerificationState, VerificationStatus } from '../../types';
import { blogApi } from '../../api/blog';
import { verificationApi } from '../../api/verification';

interface OverviewSectionProps {
  user: User;
  onNavigate: (tab: any) => void;
}

const OverviewSection: React.FC<OverviewSectionProps> = ({ user, onNavigate }) => {
  const [postCount, setPostCount] = useState(0);
  const [verificationState, setVerificationState] = useState<VerificationState | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [posts, status] = await Promise.all([
          blogApi.getMyPosts(user._id || ''),
          verificationApi.getStatus()
        ]);
        setPostCount(posts.length);
        setVerificationState(status);
      } catch (e) {
        console.error("Overview fetch error", e);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user]);

  return (
    <div className="space-y-6">
        <h2 className="text-2xl font-bold text-slate-900 dark:text-white">Dashboard Overview</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            
            {/* Account Status Card with Skeleton */}
            <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm flex flex-col h-full">
                <div className="flex items-center gap-2 mb-4">
                    <div className="p-2 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-lg">
                        <Shield size={20} />
                    </div>
                    <h3 className="font-semibold text-slate-700 dark:text-slate-300">Account Status</h3>
                </div>
                
                {loading ? (
                    <div className="space-y-4 flex-1">
                        <div className="h-12 bg-slate-100 dark:bg-slate-800/50 rounded-lg animate-pulse"></div>
                        <div className="h-12 bg-slate-100 dark:bg-slate-800/50 rounded-lg animate-pulse"></div>
                    </div>
                ) : (
                    <div className="space-y-4 flex-1">
                        <div className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-100 dark:border-slate-800">
                            <span className="text-sm font-medium text-slate-600 dark:text-slate-400">Level 1 (Email)</span>
                            {verificationState?.emailVerified ? (
                                <span className="flex items-center gap-1.5 text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 px-2 py-1 rounded-full">
                                    <CheckCircle size={12} /> Verified
                                </span>
                            ) : (
                                <span className="flex items-center gap-1.5 text-xs font-bold text-slate-500 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-full">
                                    Unverified
                                </span>
                            )}
                        </div>

                        <div className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-100 dark:border-slate-800">
                            <span className="text-sm font-medium text-slate-600 dark:text-slate-400">Level 2 (Identity)</span>
                            {verificationState?.identityVerified || verificationState?.status === VerificationStatus.FULLY_VERIFIED ? (
                                <span className="flex items-center gap-1.5 text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 px-2 py-1 rounded-full">
                                    <CheckCircle size={12} /> Verified
                                </span>
                            ) : verificationState?.identityStatus === 'pending' || verificationState?.status === VerificationStatus.PENDING ? (
                                <span className="flex items-center gap-1.5 text-xs font-bold text-yellow-600 dark:text-yellow-400 bg-yellow-50 dark:bg-yellow-900/20 px-2 py-1 rounded-full">
                                    <Clock size={12} /> Pending
                                </span>
                            ) : (
                                <span className="flex items-center gap-1.5 text-xs font-bold text-slate-500 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-full">
                                    Unverified
                                </span>
                            )}
                        </div>
                    </div>
                )}
            </div>
            
            {/* My Contributions Card with Skeleton */}
            <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm">
                <div className="flex items-center gap-2 mb-4">
                    <div className="p-2 bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 rounded-lg">
                        <FileText size={20} />
                    </div>
                    <h3 className="font-semibold text-slate-700 dark:text-slate-300">My Contributions</h3>
                </div>
                
                {loading ? (
                    <div className="space-y-4">
                        <div className="h-10 w-20 bg-slate-100 dark:bg-slate-800/50 rounded animate-pulse"></div>
                        <div className="h-4 w-32 bg-slate-100 dark:bg-slate-800/50 rounded animate-pulse"></div>
                    </div>
                ) : (
                    <>
                        <div className="text-3xl font-bold text-slate-900 dark:text-white mb-1">
                            {postCount}
                        </div>
                        <p className="text-sm text-slate-500">Total posts created</p>
                    </>
                )}
                
                <Link to="/blog/editor" className="mt-4 inline-flex items-center text-sm text-accent-600 hover:underline">
                    Write new post <ArrowLeft className="rotate-180 ml-1" size={14} />
                </Link>
            </div>
        </div>
        
        {!loading && !user.username && !user.phoneNumber && (
            <div className="bg-gradient-to-r from-indigo-500 to-purple-600 rounded-xl p-6 shadow-lg text-white flex flex-col sm:flex-row items-center justify-between gap-4">
                <div>
                    <h3 className="font-bold text-lg mb-1">Complete your Profile</h3>
                    <p className="text-indigo-100 text-sm">Add your username and details to get verified faster.</p>
                </div>
                <button 
                    onClick={() => onNavigate('profile')}
                    className="px-6 py-2 bg-white text-indigo-600 font-bold rounded-lg hover:bg-indigo-50 transition-colors shadow-md whitespace-nowrap"
                >
                    Update Profile
                </button>
            </div>
        )}
    </div>
  );
};

export default OverviewSection;
